# %% ../nbs/06_vision_inference.ipynb #a3d8ecaf-d80c-463b-84f8-197e8966b304
def _update_uid(attribute, series_obj, val='1234', slice_idx=None):
    """Updates a DICOM UID by replacing its last 4 characters with the provided value."""
    
    uid = series_obj.getDicomAttribute(attribute, slice=slice_idx)[:-4] + val
    series_obj.setDicomAttribute(attribute, uid, slice=slice_idx)
    return series_obj

# %% ../nbs/06_vision_inference.ipynb #4bd80eb1-915e-4ea1-91e0-b68738743e79
def save_series_pred(series_obj, save_dir, val='1234'):
    """Saves series prediction with updated DICOM UIDs."""
    
    series_obj.seriesInstanceUID = series_obj.seriesInstanceUID[:-4] + val
    
    for slice_idx in range(series_obj.slices):
        series_obj = _update_uid('SOPInstanceUID', series_obj, val, slice_idx)
        series_obj = _update_uid('SeriesInstanceUID', series_obj, val, slice_idx)
        
    series_obj.write(save_dir, opts={'keep_uid': True}, formats=['dicom'])

# %% ../nbs/06_vision_inference.ipynb #e4a2771e-25aa-4669-bda2-abcbe29d0504
def _to_original_orientation(input_img, org_orientation):
    """Reorients the image to its original orientation."""
    
    from SimpleITK import DICOMOrient, GetArrayFromImage
    orientation_itk = DICOMOrient(input_img, org_orientation)
    reoriented_array =  GetArrayFromImage(orientation_itk).transpose()
    
    return reoriented_array[None]

# %% ../nbs/06_vision_inference.ipynb #75a1169f-7385-4c48-9a24-51994c80732c
def _do_resize(o, target_shape, image_interpolation='linear', 
               label_interpolation='nearest'):
    """Resample images so the output shape matches the given target shape."""

    resize = Resize(
        target_shape, 
        image_interpolation=image_interpolation, 
        label_interpolation=label_interpolation
    )
    
    return resize(o)

# %% ../nbs/06_vision_inference.ipynb #shape-based-label-resize
def _signed_depth(mask: np.ndarray, spacing, margin: int = 8) -> np.ndarray:
    """Signed distance to the edge of a non-empty mask in mm: positive inside, negative outside.

    Computed on the mask's bounding box plus margin voxels, which is wide enough for cubic
    interpolation to match a full-volume distance map. Voxels outside the box get a value
    below every value inside it, so they stay outside.
    """
    outside = -4.0 * float(max(spacing))
    if mask.all():
        return np.full(mask.shape, -outside, dtype=np.float32)
    coords = np.argwhere(mask)
    lo = np.maximum(coords.min(0) - margin, 0)
    hi = np.minimum(coords.max(0) + margin + 1, mask.shape)
    box = tuple(slice(a, b) for a, b in zip(lo, hi))
    inner = mask[box]
    inner_depth = (distance_transform_edt(inner, sampling=spacing)
                   - distance_transform_edt(~inner, sampling=spacing))
    depth = np.full(mask.shape, min(outside, float(inner_depth.min())), dtype=np.float32)
    depth[box] = inner_depth
    return depth


def _resize_labels(o, target_shape, label_interpolation='shape'):
    """Resize a single-channel label image so its shape matches target_shape.

    'shape' uses shape-based interpolation: the signed distance to the edge of the
    foreground (all labels together) is resized with cubic B-spline interpolation and
    decides which voxels are foreground. With several labels, the same is done for each
    label and every foreground voxel takes the label it lies deepest inside, so labels
    that touch keep touching. A slice that falls between two source slices gets an
    outline between theirs instead of a copy of the nearest one. 'nearest' copies the
    nearest source voxel.
    """
    if label_interpolation == 'nearest':
        return _do_resize(o, target_shape, image_interpolation='nearest')
    if label_interpolation != 'shape':
        raise ValueError(
            f"label_interpolation must be 'shape' or 'nearest', got {label_interpolation!r}")
    if tuple(o.spatial_shape) == tuple(target_shape):
        return o
    if o.data.shape[0] != 1:
        raise ValueError(f"Expected a single-channel label image, got {o.data.shape[0]} channels")
    labels = o.data[0].numpy()
    values = [v for v in np.unique(labels) if v != 0]
    if not values:
        return _do_resize(o, target_shape, image_interpolation='nearest')
    masks = [labels != 0] + ([labels == v for v in values] if len(values) > 1 else [])
    depth = np.stack([_signed_depth(m, o.spacing) for m in masks])
    resized = _do_resize(ScalarImage(tensor=torch.from_numpy(depth), affine=o.affine),
                         target_shape, image_interpolation='bspline')
    values = torch.as_tensor(values, dtype=torch.float32)
    label = values[resized.data[1:].argmax(0)] if len(values) > 1 else values[0]
    restored = torch.where(resized.data[0] > 0, label, 0.)
    return type(o)(tensor=restored.unsqueeze(0).to(o.data.dtype), affine=resized.affine)


# %% ../nbs/06_vision_inference.ipynb #ee89fef9-1e9d-4d70-8c93-e44e2d600c70
def load_system_resources(models_path, learner_fn, variables_fn):
    """Load necessary resources like learner and variables."""

    learn = unwrap_compiled_model(load_learner(models_path / learner_fn, cpu=True))
    vars_fn = models_path / variables_fn
    _, apply_reorder, target_spacing = load_variables(config_fn=vars_fn)

    return learn, apply_reorder, target_spacing

# %% ../nbs/06_vision_inference.ipynb #model-only-resource-loader
def load_model_resources(model_path, device='cpu'):
    """Load a safe model artifact and its embedded standard inference config.

    This is the Safetensors-only counterpart to load_system_resources.
    """
    metadata = read_safetensors_metadata(model_path)
    inference_config = metadata.get('inference_config')
    if not isinstance(inference_config, dict):
        raise ValueError('Model artifact has no embedded inference_config.')
    if inference_config.get('workflow') != 'standard':
        raise ValueError(
            "load_model_resources requires workflow='standard'; "
            f"got {inference_config.get('workflow')!r}."
        )
    model = load_model_artifact(model_path, device=device)
    return model, inference_config

# %% ../nbs/06_vision_inference.ipynb #model-only-predict
def predict_from_config(model, inference_config, input):
    """Apply serialized item transforms, execute one input, and decode its output contract.

    The input is cast to float32 first, as images are during training.
    """
    if not isinstance(inference_config, dict) or inference_config.get('workflow') != 'standard':
        raise ValueError("predict_from_config requires a workflow='standard' inference config.")
    output_spec = inference_config.get('output')
    if not isinstance(output_spec, dict):
        raise ValueError('Standard inference config is missing its output contract.')

    if isinstance(input, Image):
        tensor = input.data
    elif isinstance(input, torch.Tensor):
        tensor = input
    else:
        tensor = torch.as_tensor(input)
    if tensor.ndim != 4:
        raise ValueError(
            'predict_from_config expects one channel-first 3D input with shape [C, D, H, W]; '
            f'got {tuple(tensor.shape)}.'
        )

    transformed = MedImage.create(tensor.float())
    for transform in transforms_from_specs(inference_config.get('item_tfms') or []):
        transformed = transform(transformed, split_idx=1)

    try:
        device = next(model.parameters()).device
    except StopIteration:
        device = torch.device('cpu')

    model.eval()
    with torch.inference_mode():
        logits = model(transformed.unsqueeze(0).to(device))
    if not isinstance(logits, torch.Tensor):
        raise TypeError(
            f'Model output must be a tensor for standard inference, got {type(logits).__name__}.'
        )

    decoded = decode_model_output(logits, output_spec)
    if isinstance(decoded, torch.Tensor):
        decoded = decoded.detach().cpu()
        if decoded.ndim and decoded.shape[0] == 1:
            decoded = decoded[0]
    return decoded

# %% ../nbs/06_vision_inference.ipynb #restore-prediction-helpers
def _prediction_save_path(save_path, fn, org_img):
    """Path to save a prediction to: save_path/'pred_<source file name>', or None without save_path.

    For a list of files, the last one names the prediction, as it is the one that gives the
    original image. Without `fn`, the file `org_img` was read from is used.
    """
    if not save_path:
        return None
    source_fn = fn if fn is None or isinstance(fn, (str, Path)) else (fn[-1] if len(fn) else None)
    source_fn = source_fn or getattr(org_img, 'path', None)
    if not source_fn:
        raise ValueError('fn is required when save_path is provided and org_img has no file path.')
    return Path(save_path) / ('pred_' + Path(source_fn).name)


def _restore_prediction(pred, org_img, input_img, org_size, label_interpolation, save_fn=None):
    """Map a predicted mask back to the original image space, then save or return it.

    The mask is padded or cropped to the preprocessed shape, resized to the original shape,
    reoriented to the original orientation and given the original affine.
    """
    pred_mask = do_pad_or_crop(pred.float(), input_img.shape[1:], padding_mode=0, mask_name=None)
    input_img.set_data(pred_mask)
    input_img = _resize_labels(input_img, org_size, label_interpolation)
    reoriented_array = _to_original_orientation(input_img.as_sitk(), ''.join(org_img.orientation))
    pred_img = ScalarImage(tensor=reoriented_array, affine=org_img.affine.copy())
    if save_fn is None:
        return pred_img
    pred_img.save(save_fn)
    return save_fn


# %% ../nbs/06_vision_inference.ipynb #model-only-spatial-inference
def inference_from_config(model, inference_config, fn: (str, Path) = '',
                          save_path: (str, Path) = None, org_img=None,
                          input_img=None, org_size=None, label_interpolation='shape'):
    """Run model-only binary/multiclass segmentation and restore original image space.

    The mask is restored with shape-based interpolation; pass
    label_interpolation='nearest' to copy the nearest voxel instead.
    """
    output_spec = inference_config.get('output') if isinstance(inference_config, dict) else None
    output_kind = output_spec.get('kind') if isinstance(output_spec, dict) else None
    if output_kind not in {'binary_segmentation', 'multiclass_segmentation'}:
        raise ValueError(
            'inference_from_config only supports binary_segmentation and '
            f'multiclass_segmentation output contracts, got {output_kind!r}.'
        )

    apply_reorder = inference_config['apply_reorder']
    target_spacing = inference_config['target_spacing']
    if org_img is None or input_img is None or org_size is None:
        org_img, input_img, org_size = med_img_reader(
            fn, apply_reorder, target_spacing, only_tensor=False
        )
    else:
        org_img, input_img = copy(org_img), copy(input_img)
    save_fn = _prediction_save_path(save_path, fn, org_img)

    pred = predict_from_config(model, inference_config, input_img)
    if not isinstance(pred, torch.Tensor):
        raise TypeError(f'Segmentation decoder returned {type(pred).__name__}, expected Tensor.')
    if pred.ndim == 3:
        pred = pred.unsqueeze(0)
    if pred.ndim != 4:
        raise ValueError(
            'Decoded segmentation must have shape [D, H, W] or [1, D, H, W]; '
            f'got {tuple(pred.shape)}.'
        )
    return _restore_prediction(pred, org_img, input_img, org_size, label_interpolation, save_fn)

# %% ../nbs/06_vision_inference.ipynb #2ba94a55-2cd1-4fae-b8b4-e82051be0cdc
def inference(learn_inf, apply_reorder, target_spacing, fn: (str, Path) = '',
              save_path: (str, Path) = None, org_img=None, input_img=None,
              org_size=None, label_interpolation='shape'):
    """Segment an image with an exported learner and restore the mask to the original image space.

    Only segmentation learners are supported: the decoded prediction is treated as a mask.

    Args:
        learn_inf: Exported segmentation learner, e.g. from `load_learner`.
        apply_reorder: Whether to reorder the image to RAS+, as in training.
        target_spacing: Voxel spacing used in training, or None to keep the original spacing.
        fn: Image path, or a list of paths stacked as channels. Not needed when
            `org_img`, `input_img` and `org_size` are given.
        save_path: Directory to save the mask in as 'pred_<file name>'. If None, the mask
            is returned instead.
        org_img: Original image, as returned by `med_img_reader(..., only_tensor=False)`.
        input_img: Preprocessed image from the same call. It is cast to float32 before
            prediction.
        org_size: Original image shape from the same call.
        label_interpolation: 'shape' (default) restores the mask with shape-based
            interpolation; 'nearest' copies the nearest voxel instead.

    Returns:
        The saved file path if `save_path` is given, otherwise the mask as a `ScalarImage`
        with the original shape, orientation and affine.
    """

    learn_inf = unwrap_compiled_model(learn_inf)

    if None in [org_img, input_img, org_size]:
        org_img, input_img, org_size = med_img_reader(fn, apply_reorder, target_spacing,
                                                      only_tensor=False)
    else:
        org_img, input_img = copy(org_img), copy(input_img)
    save_fn = _prediction_save_path(save_path, fn, org_img)

    pred, *_ = learn_inf.predict(input_img.data.float())
    return _restore_prediction(pred, org_img, input_img, org_size, label_interpolation, save_fn)

# %% ../nbs/06_vision_inference.ipynb #1730df1e-e6d7-4fa7-b40e-83f4dda26dc5
def compute_binary_tumor_volume(mask_data: Image):
    """Compute the volume of the tumor in milliliters (ml)."""
    
    dx, dy, dz = mask_data.spacing
    voxel_volume_ml = dx * dy * dz / 1000  
    return np.sum(mask_data) * voxel_volume_ml

# %% ../nbs/06_vision_inference.ipynb #a64a3407-4b97-4b1c-933c-d4a316dbff94
def refine_binary_pred_mask(pred_mask,
                            remove_size: (int, float),
                            percentage: float = 0.2,
                            verbose: bool = False) -> torch.Tensor:
    """Removes small objects from the predicted binary mask.

    Args:
        pred_mask: The (already binary) predicted mask to clean up.
        remove_size: Absolute reference object size in voxels (required, > 0).
            Objects smaller than remove_size * percentage are removed.
        percentage: Fraction of remove_size used as the cutoff. Defaults to 0.2.
        verbose: If True, print the number of components. Defaults to False.

    Returns:
        The processed mask with small objects removed.
    """
    if remove_size is None or remove_size <= 0:
        raise ValueError("remove_size must be a positive absolute object size in voxels.")

    labeled_mask, n_components = label(pred_mask)

    if verbose:
        print(n_components)

    # Handle empty mask case (no foreground components)
    if n_components == 0:
        return torch.zeros_like(torch.Tensor(pred_mask)).float()

    small_objects_threshold = remove_size * percentage
    processed_mask = remove_small_objects(labeled_mask, min_size=small_objects_threshold)

    return torch.Tensor(processed_mask > 0).float()

# %% ../nbs/06_vision_inference.ipynb #0frrjbq62loa
def keep_largest(pred_mask: torch.Tensor) -> torch.Tensor:
    """Keep only the largest connected component in a binary mask.

    Args:
        pred_mask: Binary prediction mask tensor.

    Returns:
        Binary mask with only the largest connected component.
    """
    mask_np = pred_mask.numpy() if isinstance(pred_mask, torch.Tensor) else pred_mask
    labeled_mask, n_components = label(mask_np)

    if n_components == 0:
        return torch.zeros_like(pred_mask) if isinstance(pred_mask, torch.Tensor) else mask_np

    sizes = np.bincount(labeled_mask.ravel())
    largest_label = sizes[1:].argmax() + 1  # Skip background (label 0)

    result = (labeled_mask == largest_label).astype(np.float32)
    return torch.from_numpy(result) if isinstance(pred_mask, torch.Tensor) else result
